On Wednesday, December 26, 2012 11:22:39 AM UTC-5, Andrew Gelman wrote:<br><blockquote class="gmail_quote" style="margin:0;margin-left:0.8ex;border-left:1px #ccc solid;padding-left:1ex">turk1_code &lt;- &#39;
<br>  data {
<br>    int&lt;lower=0&gt; J; // number of data points
<br>    int&lt;lower=0&gt; N; // number of names 
<br>    int&lt;lower=0&gt; y_cat0[N]; // y_cat==0
<br>    int&lt;lower=0&gt; id[N]; // name ids
<br>    int&lt;lower=0,upper=1&gt; is_cat[N]; // indicator for whether the data came from the categorical responses
<br>  }
<br>  parameters {
<br>    real a; 
<br>    real b;
<br>    real&lt;lower=0&gt; tau;
<br>    real eta[J];
<br>  }
<br>  model {
<br>    eta ~ normal (0, 1);
<br>    for (n in 1:N)
<br>      y_cat0 ~ bernoulli_logit (a + b*is_cat[n] + tau*eta[id[n]]);
<br>  }<br></blockquote>
